  const url = s.self_origin + '/hook/shopify';
  if (!force && (s.sh_hook_ok === url || Date.now() - (Number(s.sh_hook_try) || 0) < 3600000)) return null;
  await setSetting(env, 'sh_hook_try', String(Date.now()));
