{"supplier":"tedarikçi firma adı","doc_no":"belge/fatura no","date":"YYYY-AA-GG","items":[{"name":"faturadaki ürün adı","code":"tedarikçi ürün kodu varsa","qty":0,"unit":0,"amount":0,"match":"","conf":"","note":""}],"total":0}

