    const st = []; for (let i = 0; i < keys.length; i += 80) { const part = keys.slice(i, i + 80); st.push(env.DB.prepare(`UPDATE products SET mto=?1 WHERE key IN (${part.map((_, j) => '?' + (j + 2)).join(',')})`).bind(body.on ? 1 : null, ...part)); }
