        { USE.req++; return new Response(APP_HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', 'x-frame-options': 'DENY', 'referrer-policy': 'no-referrer' } }); }
      if (path.startsWith('/api/') && path !== '/api/logout' || path === '/perf' || path === '/__stats' || path === '/__run') await init(env);
      if (path === '/manifest.webmanifest') return new Response(JSON.stringify({ name: 'Lilya Backstage', short_name: 'Backstage', start_url: '/', display: 'standalone', background_color: '#f5f6f8', theme_color: '#0a0b10', icons: [{ src: '/icon-192.png', sizes: '192x192', type: 'image/png' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png' }, { src: '/apple-touch-icon.png', sizes: '180x180', type: 'image/png' }, { src: '/icon.svg', sizes: 'any', type: 'image/svg+xml' }] }), { headers: { 'content-type': 'application/manifest+json' } });
      if (path === '/apple-touch-icon.png' || path === '/icon-192.png' || path === '/icon-512.png') return new Response(Uint8Array.from(atob(path === '/icon-192.png' ? ICON_192 : path === '/icon-512.png' ? ICON_512 : ICON_PNG), c => c.charCodeAt(0)), { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400' } });
      if (path === '/icon.svg') return new Response(ICON_SVG, { headers: { 'content-type': 'image/svg+xml', 'cache-control': 'public, max-age=86400' } });
      // Giriş ekranı bilgisi: kullanıcı adı belirlenmiş mi, Face ID kurulu mu
      if (path === '/api/auth/info') {
        const user = await authUser(env); const n = await env.DB.prepare('SELECT COUNT(*) n FROM wa_creds').first();
        return json({ hasUser: !!user, passkeys: (n && n.n) || 0, authed: !!(await authed(req, env)) });
      }
